package com.lexiscan.auth; import com.lexiscan.auth.AuthDtos.*; import com.lexiscan.user.User; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { final AuthService s; public AuthController(AuthService s){this.s=s;} @PostMapping("/register") AuthResponse register(@Valid @RequestBody RegisterRequest r){return s.register(r);}@PostMapping("/login") AuthResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);}@GetMapping("/me") UserResponse me(@AuthenticationPrincipal User u){return s.view(u);} }
